SET NAMES utf8mb4;
CREATE TABLE companies (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, document VARCHAR(30) NOT NULL DEFAULT '', plan VARCHAR(40) NOT NULL DEFAULT 'Essencial', status ENUM('trial','active','blocked') NOT NULL DEFAULT 'trial');
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, company_id INT NULL, name VARCHAR(120) NOT NULL, email VARCHAR(190) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, role ENUM('platform_admin','company_admin') NOT NULL, FOREIGN KEY(company_id) REFERENCES companies(id));
CREATE TABLE clients (id INT AUTO_INCREMENT PRIMARY KEY, company_id INT NOT NULL, name VARCHAR(120) NOT NULL, phone VARCHAR(30) NOT NULL DEFAULT '', notes TEXT, FOREIGN KEY(company_id) REFERENCES companies(id));
CREATE TABLE products (id INT AUTO_INCREMENT PRIMARY KEY, company_id INT NOT NULL, name VARCHAR(120) NOT NULL, category VARCHAR(60) NOT NULL, price DECIMAL(12,2) NOT NULL, stock INT NOT NULL DEFAULT 0, FOREIGN KEY(company_id) REFERENCES companies(id));
CREATE TABLE sales (id INT AUTO_INCREMENT PRIMARY KEY, company_id INT NOT NULL, client_id INT NOT NULL, product_id INT NOT NULL, quantity INT NOT NULL, total DECIMAL(12,2) NOT NULL, paid DECIMAL(12,2) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(company_id) REFERENCES companies(id), FOREIGN KEY(client_id) REFERENCES clients(id), FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE orders (id INT AUTO_INCREMENT PRIMARY KEY, company_id INT NOT NULL, client_id INT NOT NULL, description VARCHAR(500) NOT NULL, prescription TEXT, status ENUM('received','production','ready','delivered') NOT NULL DEFAULT 'received', delivery DATE NOT NULL, FOREIGN KEY(company_id) REFERENCES companies(id), FOREIGN KEY(client_id) REFERENCES clients(id));
